const fs = require('fs');

/**
 * The program reads a log file and extracts information about log levels,
 * errors per component, unique error messages, and the busiest hour.
 */
function analyzeLogs() {
    const filePath = '/tmp/…/app.log';

    try {
        // Read the content of the log file
        const content = fs.readFileSync(filePath, 'utf8');
        const lines = content.split('\n');

        const levelCounts: Record<string, number> = {};
        const errorCounts: Record<string, number> = {};
        const uniqueErrorMessages = new Set<string>();
        const hourCounts: Record<string, number> = {};

        // Regex to match: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
        // Group 1: Hour, Group 2: Level, Group 3: Component, Group 4: Message
        const logRegex = /^\[\d{4}-\d{2}-\d{2} (\d{2}):\d{2}:\d{2}\] (\w+) \(([^)]+)\) - (.*)$/;

        for (const line of lines) {
            const trimmedLine = line.trim();
            if (!trimmedLine) continue;

            const match = trimmedLine.match(logRegex);
            if (!match) continue;

            const [_, hour, level, component, message] = match;

            // Count entries by Level
            levelCounts[level] = (levelCounts[level] || 0) + 1;

            // Count entries by Hour
            hourCounts[hour] = (hourCounts[hour] || 0) + 1;

            // Process Error specific data
            if (level === 'ERROR') {
                errorCounts[component] = (errorCounts[component] || 0) + 1;
                uniqueErrorMessages.add(message);
            }
        }

        // Determine the component with the most errors
        let maxErrorCount = -1;
        let mostErrorComponent = '';
        for (const comp in errorCounts) {
            if (errorCounts[comp] > maxErrorCount) {
                maxErrorCount = errorCounts[comp];
                mostErrorComponent = comp;
            }
        }

        // Determine the busiest hour
        let maxHourCount = -1;
        let busiestHour = '';
        for (const hour in hourCounts) {
            if (hourCounts[hour] > maxHourCount) {
                maxHourCount = hourCounts[hour];
                busiestHour = hour;
            }
        }

        // Output the Analysis
        console.log('=== Log Analysis ===');
        console.log('');
        console.log('Entries by Level:');
        const sortedLevels = Object.keys(levelCounts).sort();
        for (const level of sortedLevels) {
            console.log(`  ${level}: ${levelCounts[level]}`);
        }
        console.log('');
        console.log(`Component with Most Errors: ${mostErrorComponent} (${maxErrorCount} errors)`);
        console.log('');
        console.log('Unique Error Messages:');
        const sortedErrorMessages = Array.from(uniqueErrorMessages).sort();
        for (const msg of sortedErrorMessages) {
            console.log(`  - ${msg}`);
        }
        console.log('');
        console.log(`Busiest Hour: ${busiestHour}:00 (${maxHourCount} entries)`);

    } catch (err) {
        // If file reading fails, the program exits silently or handles error
    }
}

