import json

def merge_arrays(arr_a, arr_b):
    """
    Concatenates two arrays and removes duplicates.
    Preserves the order of items in arr_a, then adds new items from arr_b.
    """
    res = list(arr_a)
    for item in arr_b:
        if item not in res:
            res.append(item)
    return res

def deep_merge(obj_a, obj_b):
    """
    Recursively merges two JSON-like structures based on the following rules:
    - If both values are objects (dicts): merge recursively.
    - If both values are arrays (lists): concatenate and remove duplicates.
    - If scalar conflict: value from B overrides A.
    - Keys only in A or only in B are included as-is.
    """
    if isinstance(obj_a, dict) and isinstance(obj_b, dict):
        res = dict(obj_a)
        for k, v in obj_b.items():
            if k in res:
                if isinstance(res[k], dict) and isinstance(v, dict):
                    res[k] = deep_merge(res[k], v)
                elif isinstance(res[k], list) and isinstance(v, list):
                    res[k] = merge_arrays(res[k], v)
                else:
                    # Scalar conflict or type mismatch
                    res[k] = v
            else:
                # Key only in B
                res[k] = v
        return res
    elif isinstance(obj_a, list) and isinstance(obj_b, list):
        return merge_arrays(obj_a, obj_b)
    else:
        # Scalar conflict or mixed types
        return obj_b

