/**
 * Deep merges two objects based on the following rules:
 * 1. If both values are objects: merge recursively.
 * 2. If both values are arrays: concatenate and remove duplicates (preserve order, items from A first, then new items from B).
 * 3. If scalar conflict: value from B overrides A.
 * 4. Keys only in A or only in B are included as-is.
 */
function merge(objA: any, objB: any): any {
    // If both values are arrays
    if (Array.isArray(objA) && Array.isArray(objB)) {
        const result: any[] = [];
        const seen = new Set();

        // Add items from A
        for (const item of objA) {
            if (!seen.has(item)) {
                result.push(item);
                seen.add(item);
            }
        }
        // Add items from B
        for (const item of objB) {
            if (!seen.has(item)) {
                result.push(item);
                seen.add(item);
            }
        }
        return result;
    }

    // If both values are objects (and not arrays/null)
    if (
        typeof objA === 'object' && objA !== null &&
        typeof objB === 'object' && objB !== null &&
        !Array.isArray(objA) && !Array.isArray(objB)
    ) {
        const result: Record<string, any> = {};

        // Copy all keys from A
        for (const key in objA) {
            if (Object.prototype.hasOwnProperty.call(objA, key)) {
                result[key] = objA[key];
            }
        }

        // Merge keys from B
        for (const key in objB) {
            if (Object.prototype.hasOwnProperty.call(objB, key)) {
                if (Object.prototype.hasOwnProperty.call(objA, key)) {
                    // Conflict: check if both are arrays
                    if (Array.isArray(objA[key]) && Array.isArray(objB[key])) {
                        result[key] = merge(objA[key], objB[key]);
                    } 
                    // Conflict: check if both are objects
                    else if (
                        typeof objA[key] === 'object' && objA[key] !== null &&
                        typeof objB[key] === 'object' && objB[key] !== null &&
                        !Array.isArray(objA[key]) && !Array.isArray(objB[key])
                    ) {
                        result[key] = merge(objA[key], objB[key]);
                    } 
                    // Scalar or mixed type conflict: B overrides A
                    else {
                        result[key] = objB[key];
                    }
                } else {
                    // Key only in B
                    result[key] = objB[key];
                }
            }
        }
        return result;
    }

    // Default: B overrides A (for scalar or mismatched types)
    return objB;
}

/**
 * Recursively sorts object keys alphabetically at every level.
