import re

def main():
    file_path = '/tmp/…/app.log'

    level_counts = {}
    error_component_counts = {}
    unique_error_messages = set()
    hour_counts = {}

    # Pattern to match: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
    # Group 1: Date/Time, Group 2: Level, Group 3: Component, Group 4: Message
    pattern = re.compile(r'\[(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\] (\w+) \(([^)]+)\) - (.*)')

    try:
        with open(file_path, 'r') as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                match = pattern.match(line)
                if match:
                    timestamp, level, component, message = match.groups()

                    # Level counts
                    level_counts[level] = level_counts.get(level, 0) + 1

                    # Hour counts
                    # Timestamp format: 2023-10-27 10:00:00
                    time_parts = timestamp.split(' ')
                    if len(time_parts) > 1:
                        hour_time = time_parts[1]
                        hour = hour_time.split(':')[0]
                        hour_counts[hour] = hour_counts.get(hour, 0) + 1

                    # Error specific
                    if level == 'ERROR':
                        error_component_counts[component] = error_component_counts.get(component, 0) + 1
                        unique_error_messages.add(message)
    except FileNotFoundError:
        pass

    # Output
    print("=== Log Analysis ===")
    print()
    print("Entries by Level:")
    for level_name in sorted(level_counts.keys()):
        print(f"  {level_name}: {level_counts[level_name]}")
    print()

    if error_component_counts:
        max_error_comp = max(error_component_counts, key=error_component_counts.get)
        max_error_count = error_component_counts[max_error_comp]
        print(f"Component with Most Errors: {max_error_comp} ({max_error_count} errors)")
    else:
        print("Component with Most Errors: None (0 errors)")
    print()

    print("Unique Error Messages:")
    for msg in sorted(list(unique_error_messages)):
        print(f"  - {msg}")
    print()

    if hour_counts:
        max_hour_val = max(hour_counts, key=hour_counts.get)
        print(f"Busiest Hour: {int(max_hour_val):02d}:00 ({hour_counts[max_hour_val]} entries)")
    else:
        pass

if __name__ == "__main__":
    main()

