fn format_with_commas(n: u64) -> String {
            let s_val = n.to_string();
            let mut result = String::new();
            let len = s_val.len();
            for (i, c) in s_val.chars().enumerate() {
                if i > 0 && (len - i) % 3 == 0 {
                    result.push(',');
                }
                result.push(c);
            }
            result
        }

