    const filePath = '/tmp/…/graph.json';

    try {
        const content = fs.readFileSync(filePath, 'utf8');
        const data = JSON.parse(content);
        const nodes = data.nodes as string[];
        const edges = data.edges as { from: string; to: string; weight: number }[];

        // Build an adjacency list
        const adj: Record<string, { to: string; weight: number }[]> = {};
        for (const node of nodes) {
            adj[node] = [];
        }

        for (const edge of edges) {
            adj[edge.from].push({ to: edge.to, weight: edge.weight });
            adj[edge.to].push({ to: edge.from, weight: edge.weight });
        }

        // Dijkstra's Algorithm
        const dists: Record<string, number> = {};
        const visited: Set<string> = new Set();

        for (const node of nodes) {
            dists[node] = Infinity;
        }

        // Check if start node "A" exists in the graph
        if (dists.hasOwnProperty('A') === false) {
            return;
        }

        dists['A'] = 0;

        while (true) {
            let u: string | null = null;

            // Find the unvisited node with the smallest distance
            for (const node of nodes) {
                if (!visited.has(node) && (u === null || dists[node] < dists[u])) {
                    u = node;
                }
            }

            // If no node is found or the smallest distance is Infinity, we are done
            if (u === null || dists[u] === Infinity) {
                break;
            }

            visited.add(u);

            // Update distances to neighbors
            for (const edge of adj[u]) {
                if (dists[u] + edge.weight < dists[edge.to]) {
                    dists[edge.to] = dists[u] + edge.weight;
                }
            }
        }

        // Output formatting
        const sortedNodes = nodes.slice().sort();
        console.log("=== Shortest Paths from A ===");
        console.log("");
        for (const node of sortedNodes) {
            console.log(`A -> ${node}: ${dists[node]}`);
        }

    } catch (error) {
        // Handle file read or JSON parse errors gracefully
    }
}

