use std::fs::File;
use std::io::{BufRead, BufReader};
use std::collections::BTreeMap;
use std::collections::BTreeSet;

fn main() {
    let path = "/tmp/…/app.log";
    let file = File::open(path).expect("Could not open file");
    let reader = BufReader::new(file);

    let mut level_counts = BTreeMap::new();
    let mut error_counts: std::collections::HashMap<String, usize> = std::collections::HashMap::new();
    let mut error_messages = BTreeSet::new();
    let mut hour_counts = std::collections::HashMap::new();

    for line_result in reader.lines() {
        let line = line_result.expect("Failed to read line");
        if line.len() < 22 {
            continue;
        }

        // Format: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
        // The hour is at index 12 and 13.
        let hour = &line[12..14];

        // Find the level
        let end_bracket_idx = line.find(']').expect("No closing bracket");
        let level_start = end_bracket_idx + 2;
        let level_end = line[level_start..].find(' ').unwrap() + level_start;
        let level = &line[level_start..level_end];

        // Count level
        *level_counts.entry(level.to_string()).or_insert(0) += 1;

        // Count hour
        *hour_counts.entry(hour.to_string()).or_insert(0) += 1;

        // Find the component and message
