        let comp_end = line.find(')').expect("No closing parenthesis");
        let component = &line[comp_start..comp_end];

        let msg_start = line.find(" - ").expect("No separator") + 3;
        let message = &line[msg_start..];

        // Check if it's an error
        if level == "ERROR" {
            *error_counts.entry(component.to_string()).or_insert(0) += 1;
            error_messages.insert(message.to_string());
        }
    }

    println!("=== Log Analysis ==");
    println!();

    println!("Entries by Level:");
    for (level, count) in &level_counts {
        println!("  {}: {}", level, count);
