    let mut most_error_component = String::new();
    for (comp, count) in &error_counts {
        if *count > max_errors {
            max_errors = *count;
            most_error_component = comp.clone();
        }
    }
    println!("Component with Most Errors: {} ({})", most_error_component, max_errors);
    println!();

    println!("Unique Error Messages:");
    for msg in &error_messages {
        println!("  - {}", msg);
    }
    println!();

    let mut max_hour_count = 0;
    let mut busiest_hour = String::new();
    for (hour, count) in &hour_counts {
        if *count > max_hour_count {
            max_hour_count = *count;
            busiest_hour = hour.clone();
        }
    }
    println!("Busiest Hour: {}:00 ({} entries)", busiest_hour, max_hour_count);
}

