import Foundation

func shell(_ command: String) -> String {
    let task = Process()
    let pipe = Pipe()
    task.standardOutput = pipe
    task.standardError = pipe
    task.arguments = ["-c", command]
    task.executableURL = URL(fileURLWithPath: "/bin/sh")

    do {
        try task.run()
        let data = pipe.fileHandleForReading.readData()
        let output = String(data: data, encoding: .utf8) ?? ""
        return output.trimmingCharacters(in: .whitespacesAndNewlines)
    } catch {
        return ""
    }
}

let hostname = shell("hostname")
let osName = shell("uname -s")
let arch = shell("uname -m")
let user = shell("whoami")

func jsonEscape(_ str: String) -> String {
    let data = try? JSONSerialization.data(withJSONObject: str, options: .fragmentsAllowed)
    let escaped = String(data: data ?? Data(), encoding: .utf8) ?? ""
    if escaped.hasPrefix("\"") && escaped.hasSuffix("\"") {
        return String(escaped.dropFirst().dropLast())
    }
    return escaped
}

