func jsonEscape(_ str: String) -> String {
    let data = try? JSONSerialization.data(withJSONObject: str, options: .fragmentsAllowed)
    let escaped = String(data: data ?? Data(), encoding: .utf8) ?? ""
    if escaped.hasPrefix("\"") && escaped.hasSuffix("\"") {
        return String(escaped.dropFirst().dropLast())
    }
    return escaped
}

