// Function to count lines and characters
void get_file_stats(const char *path, long long *lines, long long *chars) {
    FILE *fp = fopen(path, "r");
    if (!fp) {
        *lines = 0;
        *chars = 0;
        return;
    }
    long long line_count = 0;
    int ch;
    while ((ch = fgetc(fp)) != EOF) {
        if (ch == '\n') {
            line_count++;
        }
    }
    fclose(fp);
    *lines = line_count;
    // Get size from stat
    struct stat st;
    if (stat(path, &st) == 0) {
        *chars = (long long)st.st_size;
    } else {
        *chars = 0;
    }
}

