import Foundation

func multiply(_ A: [[Int]], _ B: [[Int]]) -> [[Int]] {
    let rows = A.count
    let cols = B[0].count
    let inner = B.count
    var C = Array(repeating: Array(repeating: 0, count: cols), count: rows)
    for i in 0..<rows {
        for j in 0..<cols {
            for k in 0..<inner {
                C[i][j] += A[i][k] * B[k][j]
            }
        }
    }
    return C
}

func getSubMatrix(_ matrix: [[Int]], _ colToRemove: Int) -> [[Int]] {
    var subMatrix = [[Int]]()
    for i in 1..<matrix.count {
        var newRow = [Int]()
        for j in 0..<matrix[i].count {
            if j == colToRemove { continue }
            newRow.append(matrix[i][j])
        }
        subMatrix.append(newRow)
    }
    return subMatrix
}

func determinant(_ matrix: [[Int]]) -> Int {
    let n = matrix.count
    if n == 1 {
        return matrix[0][0]
    } else if n == 2 {
        return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0]
    } else {
        var det = 0
        for j in 0..<n {
            let subMatrix = getSubMatrix(matrix, j)
            let sign = (j % 2 == 0) ? 1 : -1
            det += sign * matrix[0][j] * determinant(subMatrix)
        }
        return det
    }
}

func formatValue(_ value: Int) -> String {
    let s = String(value)
    let padding = 4 - s.count
    return String(repeating: " ", count: padding) + s
}

func printMatrix(_ matrix: [[Int]]) {
    for row in matrix {
        let rowString = row.map { formatValue($0) }.joined(separator: " ")
        print("  " + rowString)
    }
}

