    B[0][0] = 9; B[0][1] = 8; B[0][2] = 7;
    B[1][0] = 6; B[1][1] = 5; B[1][2] = 4;
    B[2][0] = 3; B[2][1] = 2; B[2][2] = 1;

    // Allocate memory for Matrix C
    int** C = (int**)malloc(3 * sizeof(int*));
    for (int i = 0; i < 3; i++) {
        C[i] = (int*)malloc(3 * sizeof(int));
    }

    // Compute C = A x B
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            C[i][j] = 0;
            for (int k = 0; k < 3; k++) {
                C[i][j] += A[i][k] * B[k][j];
            }
        }
    }

    // Compute the determinant of the 3x3 matrix C
    // Using the standard expansion formula:
    // det = c11(c22*c33 - c23*c32) - c12(c21*c33 - c23*c31) + c13(c21*c32 - c22*c31)
    long long det = (long long)C[0][0] * ((long long)C[1][1] * C[2][2] - (long long)C[1][2] * C[2][1])
                  - (long long)C[0][1] * ((long long)C[1][0] * C[2][2] - (long long)C[1][2] * C[2][0])
                  + (long long)C[0][2] * ((long long)C[1][0] * C[2][1] - (long long)C[1][1] * C[2][0]);

