#[derive(Debug, Clone)]
enum JsonValue {
    Object(BTreeMap<String, JsonValue>),
    Array(Vec<JsonValue>),
    String(String),
    Number(f64),
    Boolean(bool),
    Null,
}

impl JsonValue {
    fn is_object_val(&self) -> bool {
        match self {
            JsonValue::Object(_) => true,
            _ => false,
        }
    }

    fn is_array_val(&self) -> bool {
        match self {
            JsonValue::Array(_) => true,
            _ => false,
        }
    }

    fn equals(&self, other: &JsonValue) -> bool {
        match (self, other) {
            (JsonValue::Object(obj1), JsonValue::Object(obj2)) => {
                if obj1.len() != obj2.len() {
                    return false;
                }
                for (k, v1) in obj1 {
                    match obj2.get(&k) {
                        Some(v2) => {
                            if !v1.equals(v2) {
                                return false;
                            }
                        }
                        None => return false,
                    }
                }
                true
            }
            (JsonValue::Array(arr1), JsonValue::Array(arr2)) => {
                if arr1.len() != arr2.len() {
                    return false;
                }
                for (i, v1) in arr1.iter().enumerate() {
                    if !v1.equals(&arr2[i]) {
                        return false;
                    }
                }
                true
            }
            (JsonValue::String(s1), JsonValue::String(s2)) => s1 == *s2,
            (JsonValue::Number(n1), JsonValue::Number(n2)) => {
                // Standard JSON numbers are compared as floats.
                // Note: NaN != NaN, but JSON spec says NaN is not allowed.
                *n1 == *n2
            }
            (JsonValue::Boolean(b1), JsonValue::Boolean(b2)) => *b1 == *b2,
            (JsonValue::Null, JsonValue::Null) => true,
            _ => false,
        }
    }
}

