impl<'a> JsonParser<'a> {
    fn parse_literal_fixed(&mut self) -> Result<JsonValue, String> {
        let start = self.pos;
        let mut current_pos = self.pos;
        while current_pos < self.input.len() {
            let c = self.input[current_pos];
            if c == 't' && &self.input[current_pos..current_pos+4] == "true" {
                self.pos += 4;
                return Ok(JsonValue::Boolean(true));
            }
            if c == 'f' && &self.input[current_pos..current_pos+5] == "false" {
