                return Ok(JsonValue::Boolean(false));
            }
            if c == 'n' && &self.input[current_pos..current_pos+4] == "null" {
                self.pos += 4;
                return Ok(JsonValue::Null);
            }
            if c == '}' || c == ']' || c == ',' || c == '"' {
                break;
            }
            current_pos += 1;
        }
        // If we reached here, it means it's not a keyword.
        // But we need to handle the fact that it might be a number.
        // Let's re-evaluate.
        let s = &self.input[start..current_pos];
        if s.parse::<f64>().is_ok() {
            let val = s.parse::<f64>().unwrap();
            self.pos = current_pos;
            return Ok(JsonValue::Number(val));
        }
        Err("Invalid literal".to_string())
    }
}

