fn determinant(matrix: &Vec<Vec<i32>>) -> i32 {
    let n = matrix.len();
    if n == 1 {
        return matrix[0][0];
    }
    if n == 2 {
        return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0];
    }
    let mut det = 0;
    for i in 0..n {
        let mut submatrix = Vec::new();
        for r in 1..n {
            let mut row = Vec::new();
            for c in 0..n {
                if c == i {
                    continue;
                }
                row.push(matrix[r][c]);
            }
            submatrix.push(row);
        }
        let sign = if i % 2 == 0 { 1 } else { -1 };
        det += sign * matrix[0][i] * determinant(&submatrix);
    }
    det
}

