            Some(JsonValue::Array(arr)) => arr.iter().filter_map(|v| {
                if let JsonValue::Object(obj) = v {
                    let from = obj.get("from").and_then(|f| if let JsonValue::String(s) = f { Some(s.clone()) } else { None });
                    let to = obj.get("to").and_then(|t| if let JsonValue::String(s) = t { Some(s.clone()) } else { None });
                    let weight = obj.get("weight").and_then(|w| if let JsonValue::Number(n) = w { Some(n) } else { None });
                    if let (Some(f), Some(t), Some(w)) = (from, to, weight) {
                        Some((f, t, w))
                    } else {
                        None
                    }
                } else {
                    None
                }
            }).collect(),
            _ => vec![],
        };

        let mut graph: HashMap<String, Vec<(String, u32)>> = HashMap::new();
        for node in &nodes {
            graph.insert(node.clone(), Vec::new());
        }
        for (from, to, weight) in edges {
            graph.get_mut(&from).unwrap().push((to.clone(), weight));
            graph.get_mut(&to).unwrap().push((from.clone(), weight));
        }

        let mut dists: HashMap<String, u32> = HashMap::new();
        for node in &nodes {
            dists.insert(node.clone(), u32::MAX);
        }
        dists.insert("A".to_string(), 0);

        let mut pq = BinaryHeap::new();
        pq.push(State { cost: 0, position: "A".to_string() });

        while let Some(State { cost, position }) = pq.pop() {
            if cost > *dists.get(&position).unwrap() {
                continue;
            }
            let neighbors = graph.get(&position).unwrap();
            for (neighbor, weight) in neighbors {
                let new_dist = cost + weight;
                if new_dist < *dists.get(neighbor).unwrap() {
                    dists.insert(neighbor.clone(), new_dist);
                    pq.push(State { cost: new_dist, position: neighbor.clone() });
                }
            }
        }

        let mut results: Vec<(String, u32)> = dists.into_iter().map(|(node, dist)| (node, dist)).collect();
        results.sort_by(|a, b| a.0.cmp(&b.0));

        println!("=== Shortest Paths from A ===");
        println!();
        for (node, dist) in results {
            println!("A -> {}: {}", node, dist);
        }
    }

