typedef struct Edge {
    int to;
    long long weight;
    struct Edge* next;
} Edge;

typedef struct {
    Edge** adj;
    int num_nodes;
} Graph;

typedef struct {
    long long dist;
    int id;
} Node_Dist;

typedef struct {
    Node_Dist* data;
    int size;
    int capacity;
} MinHeap;

void heapify(MinHeap* heap, int i) {
    int smallest = i;
    int left = 2 * i + 1;
    int right = 2 * i + 2;
    if (left < heap->size && heap->data[left].dist < heap->data[smallest].dist) {
        smallest = left;
    }
    if (right < heap->size && heap->data[right].dist < heap->data[smallest].dist) {
        smallest = right;
    }
    if (smallest != i) {
        heap->data[i] = heap->data[smallest];
        heapify(heap, smallest);
    }
}

void heap_push(MinHeap* heap, long long dist, int id) {
    if (heap->size == heap->capacity) {
        heap->data = (Node_Dist*)realloc(heap->data, sizeof(Node_Dist) * (heap->capacity * 2));
        heap->capacity *= 2;
    }
    int i = heap->size;
    heap->data[i].dist = dist;
    heap->data[i].id = id;
    heap->size++;
    while (i > 0 && heap->data[(i - 1) / 2].dist > heap->data[i].dist) {
        Node_Dist temp = heap->data[i];
        heap->data[i] = heap->data[(i - 1) / 2];
        heap->data[(i - 1) / 2] = temp;
        i = (i - 1) / 2;
    }
}

Node_Dist heap_pop(MinHeap* heap) {
    Node_Dist root = heap->data[0];
    heap->data[0] = heap->data[heap->size - 1];
    heap->size--;
    heapify(heap, 0);
    return root;
}

